package com.lamggm.rospocket;
import android.content.*;import android.view.*;import android.widget.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=31)
public class DashboardPencilTest {
 @Test public void editIsAnAccessibleSmallIconAlignedWithTheSummary(){Context c=RuntimeEnvironment.getApplication();DashboardBoard b=new DashboardBoard(c);SquareCardTest.measure(b,1200);Button edit=b.findViewWithTag("dashboard-edit");assertEquals("Edit must be a discrete48dp control, not a full-width strip",Math.round(48*c.getResources().getDisplayMetrics().density),edit.getWidth());assertEquals("",edit.getText().toString());assertEquals("Editar painel",edit.getContentDescription());TextView summary=b.findViewWithTag("dashboard-summary");assertNotNull(summary);assertEquals(summary.getTop()+summary.getHeight()/2,edit.getTop()+edit.getHeight()/2);assertTrue(edit.getLeft()>summary.getRight()-1);edit.performClick();assertTrue(b.editing());b.cancel();assertEquals(View.VISIBLE,edit.getVisibility());}
 @Test public void compactSizeLabelRemainsReadableAfterThemeTraversal(){Context c=RuntimeEnvironment.getApplication();DashboardBoard b=new DashboardBoard(c);b.bind(DashboardLayout.defaults(),null);b.addCard("watch0","Watch 1",new MetricCard(c),null);UiTheme.apply(b);b.edit();SquareCardTest.measure(b,1200);TextView label=b.findViewWithTag("layout-options:watch0");assertTrue("Size label needs drawable text width after theme remap",label.getPaint().measureText("1×1")<=label.getWidth()-label.getPaddingLeft()-label.getPaddingRight());}
}
